+					b.WriteString("<br>")
+				}
+				b.WriteByte(prefix[l])
+			}
+			b.WriteString(values[field])
+		}
+		prev = k
+	}
+	
+	// Handle the remaining part of the layout after the last field token
+	if prev < len(layout) {
