+package main
+
+import (
+	"fmt"
+	"strings"
+	
+	"github.com/bojanz/address"
+)
+
+func main() {
+	// Create a formatter
+	locale := address.NewLocale("en")
+	formatter := address.NewFormatter(locale)
+	
+	// Create an address with a layout that has text after the last field
+	addr := address.Address{
+		Line1:       "123 Main St",
+		Locality:    "Anytown",
+		Region:      "CA",
+		PostalCode:  "12345",
+		CountryCode: "US",
+	}
+	
+	// Format the address
+	result := formatter.Format(addr)
+	
+	// Print the result
+	fmt.Println("Formatted address:")
+	fmt.Println(result)
+	
+	// Check if the result contains the closing tags
+	if strings.Contains(result, "</p>") {
+		fmt.Println("SUCCESS: The formatted address contains the closing tag.")
+	} else {
+		fmt.Println("FAILURE: The formatted address is missing the closing tag.")
+	}
+}
